#include "MachineCMD_Text.h"

/*
 * LCD 页面中文文案表。
 *
 * ST7920 内置中文字库按 GB2312 编码取字模，如果直接发送 UTF-8 中文字符串，
 * 屏幕会把 UTF-8 的 3 字节序列当成多个 GB2312 字符显示。
 */
#define MACHINE_CMD_TEXT_DEFINE(name, ...)                    \
    static const uint8_t name##_data[] = {__VA_ARGS__};       \
    const MachineCmdText_s name = {name##_data,               \
                                   (uint8_t)sizeof(name##_data)}

